import 'dart:convert';
import 'package:build/build.dart';
import 'package:code_builder/code_builder.dart';
import 'package:dart_style/dart_style.dart';
import 'package:glob/glob.dart';

/// Pass 2: The Compiler
///
/// This builder sweeps up all `.builder.info` JSON files generated by Pass 1
/// and combines them into a single `stager_registry.g.dart` file using
/// [code_builder].
class BuilderCompiler implements Builder {
  @override
  Map<String, List<String>> get buildExtensions => {
        // The synthetic input r'$lib$' ensures this builder runs exactly once
        // per package and outputs a single file directly into the lib/
        // directory.
        r'$lib$': ['stager_registry.g.dart']
      };

  @override
  Future<void> build(BuildStep buildStep) async {
    // Although we avoid Map<String, dynamic> in client-facing parts of Stager,
    // the use of Map<String, dynamic> is appropriate in in this case because it
    // is loading json, which returns this value since the output can be null.
    final builders = <Map<String, dynamic>>[];
    final imports = <String>{};

    // 1. Find all intermediate JSON files generated by Pass 1.
    final assets = buildStep.findAssets(Glob('**/*.builder.info'));

    await for (final id in assets) {
      final content = await buildStep.readAsString(id);

      // Split by newline because JsonMetadataBuilder will concatenate
      // outputs if multiple @BasicBuilder annotations exist in a single file.
      final lines = content.split('\n');

      for (final line in lines) {
        final trimmed = line.trim();
        if (trimmed.isEmpty) continue;

        try {
          final json = jsonDecode(trimmed) as Map<String, dynamic>;
          builders.add(json);
          // Collect unique import paths so the generated file compiles.
          imports.add(json['importPath'] as String);
        } catch (e) {
          log.warning('Failed to parse builder info from ${id.path}: $e');
        }
      }
    }

    // If no builders were found, don't generate an empty registry.
    if (builders.isNotEmpty) {
      // 2. Generate the code using code_builder.
      final registryCode = _generateRegistryCode(builders, imports);

      // 3. Write the final output file to the lib/ directory.
      final outputId =
          AssetId(buildStep.inputId.package, 'lib/stager_registry.g.dart');
      await buildStep.writeAsString(outputId, registryCode);
    }
  }

  /// Generates the registry source code using [code_builder].
  ///
  /// [builders] is the list of metadata maps extracted in Pass 1.
  /// [imports] is the set of unique package URIs required by the builders.
  String _generateRegistryCode(
      List<Map<String, dynamic>> builders, Set<String> imports) {
    final library = Library((l) => l
      ..directives.addAll([
        Directive.import('package:stager_platform/builders/basic_builder.dart'),
        for (final path in imports) Directive.import(path),
      ])
      ..body.addAll([
        _buildGeneratedBuildersField(builders),
        _buildStagerRegistryField(),
      ]));

    final emitter = DartEmitter(orderDirectives: true);
    final source = '${library.accept(emitter)}';

    // Manually construct the header since code_builder.Library doesn't 
    // support a raw header property.
    final header = '// GENERATED CODE - DO NOT MODIFY BY HAND\n\n'
        '// **************************************************************************\n'
        '// Generator: BuilderCompiler\n'
        '// **************************************************************************\n\n';

    // Combine header and source, then run it through the official Dart formatter.
    return DartFormatter(languageVersion: DartFormatter.latestLanguageVersion)
        .format('$header$source');
  }

  /// Builds the private `_generatedBuilders` list field.
  ///
  /// This list contains all discovered [BasicBuilderHandler] instances.
  Field _buildGeneratedBuildersField(List<Map<String, dynamic>> builders) {
    return Field((f) => f
      ..name = '_generatedBuilders'
      ..modifier = FieldModifier.final$
      ..type = TypeReference((b) => b
        ..symbol = 'List'
        ..types.add(TypeReference((tr) => tr
          ..symbol = 'BasicBuilderHandler'
          ..types.add(refer('dynamic')))))
      ..assignment = literalList([
        for (final b in builders)
          TypeReference((tr) => tr
            ..symbol = 'BasicBuilderHandler'
            ..types.add(refer(b['type'] as String)))
          .newInstance([], {
            'name': literalString(b['name'] as String),
            'delegate': refer(b['delegate'] as String),
          })
      ]).code);
  }

  /// Builds the public `stagerRegistry` map field.
  ///
  /// This map allows the platform to look up builders by their reified type.
  Field _buildStagerRegistryField() {
    return Field((f) => f
      ..name = 'stagerRegistry'
      ..modifier = FieldModifier.final$
      ..type = TypeReference((b) => b
        ..symbol = 'Map'
        ..types.addAll([
          refer('Type'),
          TypeReference((tr) => tr
            ..symbol = 'BasicBuilderHandler'
            ..types.add(refer('dynamic')))
        ]))
      ..assignment = const Code('{\n'
          '  for (final builder in _generatedBuilders) builder.type: builder,\n'
          '}'));
  }
}

/// The factory function used by build.yaml
Builder builderCompilerBuilder(BuilderOptions options) {
  return BuilderCompiler();
}
